FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Nivel del componente A *)
    nivelB : BOOL; (* Nivel del componente B *)
    nivelVacio : BOOL; (* Nivel vacío del reactor *)
    btnInicio : BOOL; (* Botón de inicio *)
    btnAbort : BOOL; (* Botón de abortar *)
    temp : REAL; (* Temperatura del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula del componente A *)
    vB : BOOL; (* Válvula del componente B *)
    calentador : BOOL; (* Calentador *)
    mezclador : BOOL; (* Mezclador *)
    vDescarga : BOOL; (* Válvula de descarga *)
    fase : INT; (* Fase actual *)
END_VAR
VAR
    tMezclar : TP; (* Temporizador para mezclar *)
    inicioPulsado : BOOL := FALSE; (* Bandera para detectar pulsación de btnInicio *)
    abortPulsado : BOOL := FALSE; (* Bandera para detectar pulsación de btnAbort *)
END_VAR

(* Control de inicio *)
IF btnInicio AND NOT inicioPulsado AND fase = 0 THEN
    fase := 1;
    inicioPulsado := TRUE;
END_IF

(* Control de abort *)
IF btnAbort AND NOT abortPulsado THEN
    abortPulsado := TRUE;
    CASE fase OF
        1..4:
            vA := FALSE;
            vB := FALSE;
            calentador := FALSE;
            mezclador := FALSE;
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
        5:
            IF NOT nivelVacio THEN
                fase := 5;
            ELSE
                fase := 0;
            END_IF;
    END_CASE;
END_IF

(* Control de las fases *)
CASE fase OF
    1:
        vA := TRUE;
        IF nivelA THEN
            vA := FALSE;
            fase := 2;
        END_IF;
    2:
        vB := TRUE;
        IF nivelB THEN
            vB := FALSE;
            fase := 3;
        END_IF;
    3:
        calentador := TRUE;
        IF temp >= 60.0 THEN
            calentador := FALSE;
            fase := 4;
        END_IF;
    4:
        mezclador := TRUE;
        tMezclar(IN := TRUE, PT := T#120S);
        IF tMezclar.Q THEN
            mezclador := FALSE;
            fase := 5;
        END_IF;
    5:
        vDescarga := TRUE;
        IF nivelVacio THEN
            vDescarga := FALSE;
            fase := 0;
        END_IF;
    0:
        (* Reposo *)
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        vDescarga := FALSE;
        IF btnAbort THEN
            abortPulsado := TRUE;
        END_IF;
END_CASE

(* Reinicio de las banderas *)
IF NOT btnInicio THEN
    inicioPulsado := FALSE;
END_IF
IF NOT btnAbort THEN
    abortPulsado := FALSE;
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Sensor de nivel para componente A *)
    nivelB : BOOL; (* Sensor de nivel para componente B *)
    nivelVacio : BOOL; (* Sensor de nivel para tanque vacío *)
    btnInicio : BOOL; (* Botón de inicio de receta *)
    btnAbort : BOOL; (* Botón de aborto de receta *)
    temp : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula para componente A *)
    vB : BOOL; (* Válvula para componente B *)
    calentador : BOOL; (* Calentador del reactor *)
    mezclador : BOOL; (* Mezclador del reactor *)
    vDescarga : BOOL; (* Válvula de descarga *)
    fase : INT; (* Fase actual del proceso *)
END_VAR
VAR
    tMezcla : TON; (* Temporizador para la fase de mezcla *)
    recetaEnCurso : BOOL; (* Indicador de receta en curso *)
END_VAR

(* Inicialización de salidas y variables *)
vA := FALSE;
vB := FALSE;
calentador := FALSE;
mezclador := FALSE;
vDescarga := FALSE;

(* Control de fases del proceso *)
IF NOT recetaEnCurso THEN
    IF btnInicio THEN
        recetaEnCurso := TRUE;
        fase := 1;
    ELSE
        fase := 0;
    END_IF;
ELSE
    CASE fase OF
        1: (* Fase 1: Dosificación de A *)
            vA := NOT nivelA;
            IF nivelA THEN
                vA := FALSE;
                fase := 2;
            END_IF;
        2: (* Fase 2: Dosificación de B *)
            vB := NOT nivelB;
            IF nivelB THEN
                vB := FALSE;
                fase := 3;
            END_IF;
        3: (* Fase 3: Calentamiento *)
            calentador := temp < 60.0;
            IF temp >= 60.0 THEN
                calentador := FALSE;
                fase := 4;
                tMezcla(IN := TRUE, PT := T#120S);
            END_IF;
        4: (* Fase 4: Mezcla *)
            mezclador := tMezcla.Q;
            IF tMezcla.Q THEN
                mezclador := FALSE;
                fase := 5;
            END_IF;
        5: (* Fase 5: Descarga *)
            vDescarga := NOT nivelVacio;
            IF nivelVacio THEN
                vDescarga := FALSE;
                recetaEnCurso := FALSE;
                fase := 0;
            END_IF;
    END_CASE;
END_IF;

(* Manejo de aborto *)
IF btnAbort AND recetaEnCurso THEN
    vA := FALSE;
    vB := FALSE;
    calentador := FALSE;
    mezclador := FALSE;
    IF fase <> 5 THEN
        fase := 5;
    END_IF;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Batch
VAR_INPUT
    nivelA : BOOL; (* Sensor de nivel para componente A *)
    nivelB : BOOL; (* Sensor de nivel para componente B *)
    nivelVacio : BOOL; (* Sensor de nivel vacío del reactor *)
    btnInicio : BOOL; (* Botón de inicio de la receta *)
    btnAbort : BOOL; (* Botón de aborto de la receta *)
    temp : REAL; (* Temperatura actual del reactor *)
END_VAR
VAR_OUTPUT
    vA : BOOL; (* Válvula para dosificar componente A *)
    vB : BOOL; (* Válvula para dosificar componente B *)
    calentador : BOOL; (* Calentador del reactor *)
    mezclador : BOOL; (* Mezclador del reactor *)
    vDescarga : BOOL; (* Válvula de descarga del reactor *)
    fase : INT; (* Fase actual del proceso *)
END_VAR
VAR
    tMezcla : TON; (* Temporizador para la fase de mezcla *)
    recetaEnCurso : BOOL; (* Indica si la receta está en curso *)
END_VAR

(* Control de la receta por lotes *)
IF NOT recetaEnCurso THEN
    IF btnInicio AND (fase = 0) THEN
        recetaEnCurso := TRUE;
        fase := 1;
    END_IF;
ELSE
    CASE fase OF
        1: (* Fase 1: Dosificación de A *)
            vA := NOT nivelA;
            IF nivelA THEN
                vA := FALSE;
                fase := 2;
            END_IF;
        2: (* Fase 2: Dosificación de B *)
            vB := NOT nivelB;
            IF nivelB THEN
                vB := FALSE;
                fase := 3;
            END_IF;
        3: (* Fase 3: Calentamiento *)
            calentador := (temp < 60.0);
            IF temp >= 60.0 THEN
                calentador := FALSE;
                fase := 4;
                tMezcla(IN := TRUE, PT := T#120S);
            END_IF;
        4: (* Fase 4: Mezcla *)
            mezclador := tMezcla.Q;
            IF NOT tMezcla.Q THEN
                mezclador := FALSE;
                fase := 5;
            END_IF;
        5: (* Fase 5: Descarga *)
            vDescarga := NOT nivelVacio;
            IF nivelVacio THEN
                vDescarga := FALSE;
                recetaEnCurso := FALSE;
                fase := 0;
            END_IF;
    END_CASE;

    (* Manejo del botón de aborto *)
    IF btnAbort THEN
        vA := FALSE;
        vB := FALSE;
        calentador := FALSE;
        mezclador := FALSE;
        IF fase <> 5 THEN
            fase := 5;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq  : BOOL; (* Solicitud de transmisión *)
    rxOk   : BOOL; (* Confirmación de recepción del dispositivo externo *)
    rxData : INT;  (* Dato recibido (eco) *)
END_VAR

VAR_OUTPUT
    txData   : INT;  (* Dato transmitido *)
    ocupado  : BOOL; (* Intercambio en curso *)
    ok       : BOOL; (* Último intercambio exitoso *)
    error    : BOOL; (* Fallaron los 3 intentos *)
    nIntentos: INT;  (* Número de intento en curso / último *)
END_VAR

VAR
    txReq_prev : BOOL;        (* Valor anterior de txReq para detectar flanco *)
    timer      : TON;         (* Temporizador de plazo por intento *)
    timerRun   : BOOL;        (* Habilita el temporizador *)
    TEST_VALUE : INT := 100;  (* Valor de prueba fijo *)
    MAX_INT    : INT := 3;    (* Máximo número de intentos *)
END_VAR

(* ── Temporizador ── *)
timer(IN := timerRun, PT := T#500MS);

(* ── Detección de flanco ascendente en txReq ── *)
IF txReq AND NOT txReq_prev THEN
    IF NOT ocupado THEN
        (* Iniciar nuevo intercambio *)
        ok        := FALSE;
        error     := FALSE;
        ocupado   := TRUE;
        nIntentos := 1;
        txData    := TEST_VALUE;
        timerRun  := TRUE;   (* Arrancar temporizador del intento 1 *)
    END_IF;
    (* Si ocupado = TRUE, el flanco se ignora *)
END_IF;

(* ── Lógica principal durante un intercambio ── *)
IF ocupado THEN

    IF rxOk THEN
        (* Ha llegado respuesta del dispositivo *)
        IF rxData = txData THEN
            (* ── Intento correcto ── *)
            timerRun := FALSE;
            ocupado  := FALSE;
            ok       := TRUE;
        ELSE
            (* ── Respuesta incorrecta: tratar como fallo de intento ── *)
            timerRun := FALSE;          (* Detener y resetear temporizador *)
            IF nIntentos < MAX_INT THEN
                nIntentos := nIntentos + 1;
                timerRun  := TRUE;      (* Nuevo plazo para el siguiente intento *)
            ELSE
                (* Agotados los 3 intentos *)
                ocupado := FALSE;
                error   := TRUE;
            END_IF;
        END_IF;

    ELSIF timer.Q THEN
        (* ── Plazo vencido sin confirmación ── *)
        timerRun := FALSE;              (* Resetear temporizador *)
        IF nIntentos < MAX_INT THEN
            nIntentos := nIntentos + 1;
            timerRun  := TRUE;          (* Nuevo plazo para el siguiente intento *)
        ELSE
            (* Agotados los 3 intentos *)
            ocupado := FALSE;
            error   := TRUE;
        END_IF;
    END_IF;

END_IF;

(* ── Guardar estado anterior de txReq ── *)
txReq_prev := txReq;

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL; (* Petición de transmisión *)
    rxOk : BOOL; (* Confirmación de recepción *)
    rxData : INT; (* Datos recibidos *)
END_VAR
VAR_OUTPUT
    txData : INT; (* Datos a transmitir *)
    ocupado : BOOL; (* Estado ocupado *)
    ok : BOOL; (* Confirmación de éxito *)
    error : BOOL; (* Confirmación de error *)
    nIntentos : INT; (* Número de intentos *)
END_VAR
VAR
    tEspera : TP; (* Temporizador de espera *)
    estado : INT; (* Estado actual del intercambio *)
    intentos : INT; (* Contador de intentos *)
END_VAR

(* Estados: 0 - Inactivo, 1 - En espera de respuesta, 2 - Éxito, 3 - Error *)
IF txReq AND NOT ocupado THEN
    estado := 1;
    intentos := 1;
    txData := 100;
    ocupado := TRUE;
    tEspera(IN := TRUE, PT := T#500MS);
END_IF

IF estado = 1 THEN
    IF tEspera.Q THEN
        IF rxOk AND rxData = txData THEN
            estado := 2;
            ok := TRUE;
        ELSE
            estado := 3;
            error := TRUE;
        END_IF
        ocupado := FALSE;
    END_IF
END_IF

IF estado = 3 AND intentos < 3 THEN
    estado := 1;
    intentos := intentos + 1;
    tEspera(IN := TRUE, PT := T#500MS);
END_IF

nIntentos := intentos;

IF estado = 2 THEN
    ocupado := FALSE;
    ok := TRUE;
END_IF

IF estado = 3 AND intentos = 3 THEN
    ocupado := FALSE;
    error := TRUE;
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL;  // Petición de transmisión
    rxOk  : BOOL;  // Confirmación de recepción
    rxData: INT;   // Datos recibidos
END_VAR

VAR_OUTPUT
    txData  : INT;  // Datos a transmitir
    ocupado : BOOL; // Indica si se está ocupado en un intercambio
    ok      : BOOL; // Indica si el intercambio fue exitoso
    error   : BOOL; // Indica si el intercambio falló
    nIntentos: INT;  // Número de intentos realizados
END_VAR

VAR
    estado    : INT := 0; // Estado del intercambio (0: Idle, 1: Enviando, 2: Esperando respuesta)
    intentos  : INT := 0; // Contador de intentos
    timer     : TON;     // Temporizador para esperar la respuesta
    valorTx   : INT := 0; // Valor a transmitir
    inicioIntercambio : BOOL := FALSE; // Indica si se ha iniciado un intercambio
END_VAR

// Inicialización del temporizador
timer(IN := FALSE, PT := T#500MS);

// Máquina de estados
CASE estado OF
    0: // Estado Idle
        IF txReq AND NOT inicioIntercambio THEN
            inicioIntercambio := TRUE;
            estado := 1;
            intentos := 1;
            nIntentos := intentos;
            valorTx := 100;
            txData := valorTx;
            ocupado := TRUE;
            timer(IN := TRUE);
        END_IF

    1: // Estado Enviando
        IF rxOk AND (rxData = valorTx) THEN
            estado := 0;
            ok := TRUE;
            ocupado := FALSE;
            inicioIntercambio := FALSE;
        ELSIF timer.Q THEN
            IF intentos < 3 THEN
                intentos := intentos + 1;
                nIntentos := intentos;
                timer(IN := TRUE);
            ELSE
                estado := 0;
                error := TRUE;
                ocupado := FALSE;
                inicioIntercambio := FALSE;
            END_IF
        END_IF

    2: // Estado Esperando respuesta
        // Este estado no se utiliza en este código, pero se mantiene por claridad.
        // El estado de espera se maneja en el estado 1.
END_CASE

// Mantener ok y error activos hasta el siguiente intercambio
IF estado = 0 THEN
    IF ok THEN
        ok := FALSE;
    END_IF
    IF error THEN
        error := FALSE;
    END_IF
END_IF

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL; (* Solicitud de transmisión *)
    rxOk : BOOL; (* Confirmación de recepción *)
    rxData : INT; (* Datos recibidos *)
END_VAR
VAR_OUTPUT
    txData : INT; (* Datos a transmitir *)
    ocupado : BOOL; (* Indica si el intercambio está en curso *)
    ok : BOOL; (* Indica si el intercambio fue exitoso *)
    error : BOOL; (* Indica si el intercambio falló *)
    nIntentos : INT; (* Número de intento actual *)
END_VAR
VAR
    intentoActual : INT := 0; (* Contador de intentos *)
    valorPrueba : INT := 100; (* Valor de prueba a transmitir *)
    tLimite : TON; (* Temporizador de límite de tiempo *)
    txReqAnt : BOOL := FALSE; (* Estado anterior de txReq *)
    intercambioEnCurso : BOOL := FALSE; (* Estado del intercambio *)
END_VAR

(* Detectar flanco ascendente de txReq *)
IF txReq AND NOT txReqAnt THEN
    IF NOT intercambioEnCurso THEN
        (* Iniciar nuevo intercambio *)
        txData := valorPrueba;
        ocupado := TRUE;
        ok := FALSE;
        error := FALSE;
        intentoActual := 1;
        intercambioEnCurso := TRUE;
        tLimite(IN := TRUE, PT := T#500MS);
    END_IF;
END_IF;

(* Control de intentos y recepción *)
IF intercambioEnCurso THEN
    IF tLimite.Q THEN
        (* Tiempo límite alcanzado, intento fallido *)
        intentoActual := intentoActual + 1;
        IF intentoActual > 3 THEN
            (* Todos los intentos fallaron *)
            error := TRUE;
            ocupado := FALSE;
            intercambioEnCurso := FALSE;
        ELSE
            (* Iniciar nuevo intento *)
            tLimite(IN := TRUE, PT := T#500MS);
        END_IF;
    ELSIF rxOk AND (rxData = valorPrueba) THEN
        (* Intento exitoso *)
        ok := TRUE;
        ocupado := FALSE;
        intercambioEnCurso := FALSE;
    END_IF;
END_IF;

(* Actualizar salidas *)
nIntentos := intentoActual;

(* Almacenar estado anterior de txReq *)
txReqAnt := txReq;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Com
VAR_INPUT
    txReq : BOOL;  (* Peticion de transmision *)
    rxOk : BOOL;   (* Confirmacion de recepcion *)
    rxData : INT;  (* Datos recibidos (eco) *)
END_VAR
VAR_OUTPUT
    txData : INT;  (* Datos a transmitir *)
    ocupado : BOOL;(* Intercambio en curso *)
    ok : BOOL;     (* Intercambio correcto *)
    error : BOOL;  (* Intercambio fallido tras 3 intentos *)
    nIntentos : INT; (* Numero de intento actual *)
END_VAR
VAR
    flancoReq : R_TRIG; (* Detector de flanco para txReq *)
    flancoRx : R_TRIG;  (* Detector de flanco para rxOk *)
    temporizador : TON; (* Temporizador de 500 ms *)
    resetTemp : BOOL;   (* Señal para reiniciar el temporizador *)
END_VAR

(* Deteccion de flancos *)
flancoReq(CLK := txReq);
flancoRx(CLK := rxOk);

(* Inicio de un nuevo intercambio si no esta ocupado *)
IF flancoReq.Q AND NOT ocupado THEN
    ocupado := TRUE;
    ok := FALSE;
    error := FALSE;
    nIntentos := 1;
    txData := 100;
    resetTemp := TRUE;
ELSE
    resetTemp := FALSE;
END_IF;

(* Temporizador del intento en curso (se reinicia con resetTemp) *)
temporizador(IN := ocupado AND NOT resetTemp, PT := T#500MS);

(* Logica durante el intercambio *)
IF ocupado THEN
    (* Evaluacion de la respuesta *)
    IF flancoRx.Q THEN
        IF rxData = txData THEN
            (* Respuesta correcta (eco valido) *)
            ok := TRUE;
            ocupado := FALSE;
        ELSE
            (* Respuesta incorrecta: falla el intento *)
            IF nIntentos < 3 THEN
                nIntentos := nIntentos + 1;
                resetTemp := TRUE;
            ELSE
                error := TRUE;
                ocupado := FALSE;
            END_IF;
        END_IF;
    (* Evaluacion del timeout *)
    ELSIF temporizador.Q THEN
        IF nIntentos < 3 THEN
            nIntentos := nIntentos + 1;
            resetTemp := TRUE;
        ELSE
            error := TRUE;
            ocupado := FALSE;
        END_IF;
    END_IF;
END_IF;
END_FUNCTION_BLOCK

